# RFD 0011 §5 — Databricks run URL in Airflow task log for click-through ops
"""Write the Databricks run page URL into the Airflow task log.

When a Databricks job task succeeds, the run_id is pushed to XCom by the
DatabricksRunNowOperator. This callback reads the run_id and the workspace
URL (from an Airflow Variable) and logs the Databricks run page URL so
on-call can click through directly from the Airflow task log to the run.
"""
import logging

from airflow.models import Variable

logger = logging.getLogger(__name__)


def callback(context):
    """Airflow on_success_callback handler.

    Args:
        context: Airflow task context dict provided to callbacks.
    """
    ti = context.get("task_instance")
    if ti is None:
        return

    run_id = ti.xcom_pull(key="run_id")
    if not run_id:
        logger.debug("No Databricks run_id in XCom; nothing to log")
        return

    try:
        workspace_url = Variable.get("databricks_workspace_url")
    except KeyError:
        logger.warning(
            "databricks_workspace_url not set in Airflow Variables; "
            "Databricks run URL cannot be logged"
        )
        return

    # Standard Databricks run page URL pattern
    run_url = f"{workspace_url.rstrip('/')}/#job/{run_id}"
    logger.info(f"Databricks run URL: {run_url}")
